// ============================================================
// CODE — "Vérifier les sculptures Meshy" (workflow: Atelier Figurines 3D - Suivi Meshy)
// Toutes les minutes : regarde les figurines en cours de sculpture,
// et dès que Meshy a fini, envoie la 3D à l'ami avec les boutons de validation.
// ⚠️ À REMPLIR : les mêmes valeurs que dans le workflow "Bot ami".
// ============================================================
const CONFIG = {
  TELEGRAM_TOKEN: 'A_REMPLIR_token_botfather',
  SUPABASE_URL: 'https://bmvytqfddrfgcgokoxfn.supabase.co',
  SUPABASE_SERVICE_KEY: 'A_REMPLIR_service_role_key',
  MESHY_KEY: 'A_REMPLIR_cle_api_meshy',
  APP_URL: 'https://bigandfranck89-prog.github.io/atelier-figurines-3d',
};
if (CONFIG.MESHY_KEY.startsWith('A_REMPLIR') || CONFIG.TELEGRAM_TOKEN.startsWith('A_REMPLIR')) return [];

const sb = async (method, path, body) => this.helpers.httpRequest({
  method, url: `${CONFIG.SUPABASE_URL}/rest/v1/${path}`,
  headers: { apikey: CONFIG.SUPABASE_SERVICE_KEY, Authorization: `Bearer ${CONFIG.SUPABASE_SERVICE_KEY}`,
    Prefer: 'return=representation', 'Content-Type': 'application/json' },
  body, json: true,
});
const tg = async (method, body) => this.helpers.httpRequest({
  method: 'POST', url: `https://api.telegram.org/bot${CONFIG.TELEGRAM_TOKEN}/${method}`, body, json: true,
}).catch(e => ({ error: String(e && e.message || e) }));

const enCours = await sb('GET',
  'atelier_figurines?statut=eq.3d_en_cours&meshy_task_id=not.is.null&model_url=is.null&limit=10');
const out = [];

for (const fig of (enCours || [])) {
  try {
    const task = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.meshy.ai/openapi/v1/image-to-3d/${fig.meshy_task_id}`,
      headers: { Authorization: `Bearer ${CONFIG.MESHY_KEY}` }, json: true,
    });
    const statut = task && task.status;

    if (statut === 'SUCCEEDED') {
      const glb = task.model_urls && (task.model_urls.glb || task.model_urls.obj);
      await sb('PATCH', `atelier_figurines?id=eq.${fig.id}`,
        { model_url: glb, maj_le: new Date().toISOString() });
      await sb('POST', 'atelier_iterations',
        { figurine_id: fig.id, etape: '3d', version: 1, resultat_url: glb });
      const viewer = `${CONFIG.APP_URL}/viewer.html?src=${encodeURIComponent(glb)}`;
      const apercu = task.thumbnail_url;
      if (apercu) await tg('sendPhoto', { chat_id: fig.telegram_chat_id, photo: apercu, caption: '🗿 Ta figurine 3D est prête !' });
      await tg('sendMessage', { chat_id: fig.telegram_chat_id,
        text: `👉 Regarde-la sous tous les angles ici :\n${viewer}\n\nQu'est-ce que tu en dis ?${fig.licence ? '\n\n⚠️ Personnage sous licence : impression PERSO uniquement — interdit à la vente.' : ''}`,
        reply_markup: { inline_keyboard: [
          [{ text: '✅ Je valide la 3D', callback_data: `v_3d:${fig.id}` }],
          [{ text: '🔁 Relancer la sculpture 3D', callback_data: `r_3d:${fig.id}` },
           { text: '↩️ Modifier l\'image', callback_data: `b_img:${fig.id}` }],
        ]} });
      out.push({ json: { figurine: fig.id, statut: 'prete' } });
    }
    else if (statut === 'FAILED' || statut === 'CANCELED') {
      await sb('PATCH', `atelier_figurines?id=eq.${fig.id}`,
        { statut: 'image_validee', meshy_task_id: null, maj_le: new Date().toISOString() });
      await tg('sendMessage', { chat_id: fig.telegram_chat_id,
        text: '😕 La sculpture 3D a échoué (ça arrive). On peut réessayer ou modifier l\'image.',
        reply_markup: { inline_keyboard: [[
          { text: '🔁 Réessayer', callback_data: `r_3d:${fig.id}` },
          { text: '↩️ Modifier l\'image', callback_data: `b_img:${fig.id}` }]] } });
      out.push({ json: { figurine: fig.id, statut: 'echec' } });
    }
    else {
      out.push({ json: { figurine: fig.id, statut: statut || 'en_cours', avancement: task && task.progress } });
    }
  } catch (e) {
    out.push({ json: { figurine: fig.id, erreur: String(e && e.message || e) } });
  }
}
return out.length ? out : [{ json: { rien_en_cours: true } }];
